import{_ as t,o as a,c as i,a2 as o}from"./chunks/framework.CDEKL17z.js";const u=JSON.parse('{"title":"Quickstart","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quickstart.md","filePath":"guide/quickstart.md"}'),r={name:"guide/quickstart.md"};function s(n,e,d,h,l,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="quickstart" tabindex="-1">Quickstart <a class="header-anchor" href="#quickstart" aria-label="Permalink to &quot;Quickstart&quot;">​</a></h1><p>You need Docker and about five minutes. No clone, no Node toolchain, no account anywhere: the image is public at <code>ghcr.io/beany-vu/michi-chat</code>.</p><h2 id="_1-get-the-three-files" tabindex="-1">1. Get the three files <a class="header-anchor" href="#_1-get-the-three-files" aria-label="Permalink to &quot;1. Get the three files&quot;">​</a></h2><p>Download the contents of <a href="https://github.com/beany-vu/michi-chat/tree/master/examples/quickstart" target="_blank" rel="noreferrer"><code>examples/quickstart/</code></a> into an empty directory:</p><ul><li><code>docker-compose.yml</code> - the app image, LiteLLM, and Postgres (pgvector)</li><li><code>.env.example</code> - the settings template</li><li><code>litellm.config.yaml</code> - which real models serve the app&#39;s model aliases</li></ul><h2 id="_2-configure" tabindex="-1">2. Configure <a class="header-anchor" href="#_2-configure" aria-label="Permalink to &quot;2. Configure&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>Open <code>.env</code> and set the three required values (the stack refuses to start without them):</p><table tabindex="0"><thead><tr><th>Variable</th><th>What it is</th></tr></thead><tbody><tr><td><code>MICHI_ADMIN_PASSWORD</code></td><td>Login for the operator UI at <code>/admin</code></td></tr><tr><td><code>MICHI_CHAT_LITELLM_KEY</code></td><td>Any long random string; shared between app and proxy</td></tr><tr><td><code>MICHI_DB_PASSWORD</code></td><td>Any random string; the database is not exposed outside Docker</td></tr></tbody></table><p>Then pick a model backend - local Ollama works out of the box if you pull three models; a hosted provider is a small yaml edit. See <a href="./models">Model backends</a>.</p><h2 id="_3-run" tabindex="-1">3. Run <a class="header-anchor" href="#_3-run" aria-label="Permalink to &quot;3. Run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>Migrations run automatically on first boot. Then:</p><ul><li><strong><a href="http://localhost:3001" target="_blank" rel="noreferrer">http://localhost:3001</a></strong> - the seeded <strong>demo tenant</strong> (Mugshot Artisan Cafe, sample data), so you can try the chat immediately</li><li><strong><a href="http://localhost:3001/admin" target="_blank" rel="noreferrer">http://localhost:3001/admin</a></strong> - the operator UI: create your own tenant, write its persona, enable tools, add knowledge</li></ul><p>The demo tenant is just that - a demo. Your real bot is a new tenant you create in the admin UI.</p><h2 id="where-things-run" tabindex="-1">Where things run <a class="header-anchor" href="#where-things-run" aria-label="Permalink to &quot;Where things run&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>Image</th><th>Notes</th></tr></thead><tbody><tr><td>app</td><td><code>ghcr.io/beany-vu/michi-chat</code></td><td>Next.js UI + API, migrations on boot</td></tr><tr><td>litellm</td><td>pinned by digest</td><td>One OpenAI-compatible door to any provider</td></tr><tr><td>db</td><td><code>pgvector/pgvector:pg17</code></td><td>Required: a migration enables the vector extension</td></tr></tbody></table><p>Everything binds to <code>127.0.0.1</code> only. For anything public-facing, put a reverse proxy in front - see <a href="./security">Security model</a>.</p>',18)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
